import{_ as e,o as n,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"SVG-Line – draw and animate connections","description":"","frontmatter":{"title":"SVG-Line – draw and animate connections"},"headers":[],"relativePath":"en/projects/grafik-visual-studio/svg-line.md","filePath":"en/projects/grafik-visual-studio/svg-line.md","lastUpdated":1793123358000}'),i={name:"en/projects/grafik-visual-studio/svg-line.md"};function s(r,t,d,l,c,g){return n(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="svg-line" tabindex="-1">SVG-Line <a class="header-anchor" href="#svg-line" aria-label="Permalink to &quot;SVG-Line&quot;">​</a></h1><h2 id="changes-through-studio-0-1-285" tabindex="-1">Changes through Studio 0.1.285 <a class="header-anchor" href="#changes-through-studio-0-1-285" aria-label="Permalink to &quot;Changes through Studio 0.1.285&quot;">​</a></h2><ul><li><strong>Vertical starting position</strong> under <strong>Line</strong> applies to SVG lines and Value connections. Unchecked means a horizontal free starting position. Vertical automatic orthogonal routes leave the start vertically and turn left or right at target height. Docked lines support this routing too; explicit intermediate points retain priority.</li><li>Point drags start after <strong>6 screen pixels</strong> of movement. Individual handles do not initiate group movement or jump to the pointer. The other endpoint retains its binding. <strong>Ctrl + drag</strong> detaches a single docked endpoint; <strong>Alt + drag on the line</strong> moves a docked line as a whole and detaches both endpoints.</li><li>Explicit <strong>z-index −100 or lower</strong> hides an SVG line only in runtime. It remains editable and continues forwarding values, including Number-to-Math inputs. Editor stacking is independent.</li><li>From <strong>0.1.282</strong>, active industrial rotary/linear outputs directly control the connected SVG line&#39;s speed and direction without an extra numeric entity. Use the <strong>rotary / SVG LineBox divisor</strong>: 10 / 10 = 1 cycle/s; 20 / 10 = 2 cycles/s. Zero stops animation; negatives reverse direction. With divisor 1, magnitudes of 20 or greater reach the 20 cycles/s limit. Disable automatic rotary/LineBox divisor adjustment for value-dependent speed; enabling it deliberately maintains the target speed. Value connections themselves are not animated.</li></ul><p>See the editor setup and animated runtime demo in the <a href="./bildergalerie">gallery</a>.</p><p>From Studio 0.1.136, <strong>automatic divisor adjustment</strong> is available for numeric entities and LineBox outputs. It keeps animation at an adjustable speed as power changes. See <strong>Automatic divisor adjustment: how and why</strong> below for setup and calculation details.</p><p>Find <strong>SVG-Line</strong> under <strong>HA Grafik – Spezial</strong>. It visually connects widgets, routes paths around corners, and can animate a value flow. A line can start or end at a widget docking point, an explicitly enabled collector point on another SVG-Line, or free coordinates. The line itself is not a Home Assistant entity; an optional entity controls its animation.</p><h2 id="connect-widgets" tabindex="-1">Connect widgets <a class="header-anchor" href="#connect-widgets" aria-label="Permalink to &quot;Connect widgets&quot;">​</a></h2><ol><li>Add SVG-Line and select it. Its start and end appear as draggable circles.</li><li>Enable <strong>Docking points</strong> on the target widget and activate the positions you need. New widgets start with all twelve positions off: left/right at top, center and bottom; top/bottom at one-quarter, center and three-quarter width. <strong>All points</strong> switches them together. More than one line can occupy the same point.</li><li>Drag a line endpoint onto an active docking point. Alternatively, choose the widget and point under <strong>Start</strong> and <strong>Target</strong>. <strong>Active collector point instead</strong> chooses a collector on another SVG-Line; <strong>Free X/Y</strong> positions an unattached end.</li></ol><table tabindex="0"><thead><tr><th>Editor action</th><th>Result</th></tr></thead><tbody><tr><td>Drag a free endpoint</td><td>Moves the start or end. Arrow keys move a focused point by 1 pixel, or 10 pixels with <code>Shift</code>.</td></tr><tr><td>Hold <code>Ctrl</code> and drag a docked endpoint</td><td>Detaches and moves it. <code>Ctrl</code> plus an arrow key also works.</td></tr><tr><td>Drag an intermediate point</td><td>Changes a manual multi-point path.</td></tr><tr><td>Drag the line itself</td><td>Drag free lines directly; hold <code>Alt</code> for docked lines. Moves the entire line and detaches its existing start/target docking.</td></tr><tr><td>Click the line without dragging</td><td>Opens the <strong>Intermediate point</strong>, <strong>Collector point</strong> or <strong>Value output point</strong> choice; <strong>OK</strong> inserts the point.</td></tr></tbody></table><h2 id="paths-and-collector-points" tabindex="-1">Paths and collector points <a class="header-anchor" href="#paths-and-collector-points" aria-label="Permalink to &quot;Paths and collector points&quot;">​</a></h2><h3 id="value-output-point-for-a-freely-placed-display" tabindex="-1">Value output point for a freely placed display <a class="header-anchor" href="#value-output-point-for-a-freely-placed-display" aria-label="Permalink to &quot;Value output point for a freely placed display&quot;">​</a></h3><p>From Studio <strong>0.1.275</strong>, <strong>Value output point</strong> is the third point type. It forwards the SVG line&#39;s value, such as its numeric animation entity or connected source value. The editor shows an octagon; configure its color under <strong>Settings → Value output point</strong>. It is output-only and cannot be the destination of another line.</p><p>From <strong>0.1.281</strong>, a value output point can move only <strong>along the visible line path</strong>. Dragging keeps it at the nearest point on the line, including curves and rounded corners. It changes neither the line path nor the selected routing mode. Only intermediate and collector points shape the path. The outgoing display connection follows the new position after moving the point. Older off-path points and manually entered positions are projected onto the path.</p><ol><li>Select the SVG line, click the desired position again and add a <strong>Value output point</strong>.</li><li>Place a <strong>Number</strong> widget beside, above or below the line. Under <strong>Data flow</strong>, enable its <strong>Input point</strong> and choose its side.</li><li>Add a connection. Under <strong>Start → Collector or value output point</strong>, select the new point or drag the start onto it. Connect the destination to Number&#39;s input.</li></ol><p>The point and outgoing connection are automatically hidden in runtime; forwarding remains active. The original SVG line stays visible. <strong>String</strong> can display a text value from data flow in the same way. Use <strong>Line points</strong> to edit names, positions and point types later. Unknown values are not replaced with an invented zero.</p><p>Under <strong>Path and collector points</strong>, <strong>Path mode</strong> offers <strong>Straight</strong>, <strong>Automatic orthogonal</strong>, <strong>Curve</strong>, and <strong>Manual zigzag/multi-point path</strong>. <strong>Corner radius</strong> rounds corners where the chosen path supports them. <strong>Intermediate and collector points</strong> lets you name, position, and edit points. Adding an intermediate or collector point by clicking changes the path to manual multi-point mode.</p><p>An <strong>intermediate point</strong> only bends the path. An enabled <strong>collector point</strong> accepts other SVG-Lines. Drag their free endpoint onto the visible collector or select it in the properties. Several lines can share one collector. Crossing or touching lines never join automatically. A disabled collector cannot accept a new connection.</p><h2 id="line-and-arrowheads" tabindex="-1">Line and arrowheads <a class="header-anchor" href="#line-and-arrowheads" aria-label="Permalink to &quot;Line and arrowheads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Controls</th></tr></thead><tbody><tr><td><strong>Line</strong></td><td><strong>Base color</strong>, <strong>animation color</strong>, <strong>width</strong> (1–40 px), <strong>opacity</strong>, <strong>style</strong> (solid, dashed, dotted), <strong>dash length</strong>, <strong>gap length</strong>, and <strong>line caps</strong> (round, butt, square).</td></tr><tr><td><strong>Arrowheads</strong></td><td>Configure start and end independently: none, filled arrow, open arrow, or circle. Set <strong>size</strong> and <strong>color</strong>. The displayed marker ends swap when the flow reverses.</td></tr></tbody></table><h2 id="animation-and-direction-source" tabindex="-1">Animation and direction source <a class="header-anchor" href="#animation-and-direction-source" aria-label="Permalink to &quot;Animation and direction source&quot;">​</a></h2><p>Enable <strong>Animation</strong> and choose two-color flow, moving dashes, pulse, or moving light. Exactly one <strong>direction source</strong> applies:</p><table tabindex="0"><thead><tr><th>Source</th><th>Direction and speed</th></tr></thead><tbody><tr><td><strong>Manual</strong></td><td>Start → end or end → start, with a <strong>duration</strong> of 0.2–20 seconds per cycle. When joined to a collector, manual flow points towards it.</td></tr><tr><td><strong>Numeric entity</strong></td><td>Positive values flow start → end, negative values reverse it, and <code>0</code> stops. Absolute value ÷ <strong>divisor</strong> (default <code>1</code>) gives cycles per second, limited to 0.05–20. Example: <code>1000 W ÷ 100 = 10</code> cycles/s.</td></tr><tr><td><strong>Boolean entity</strong></td><td><code>on</code>/<code>true</code>/<code>1</code> runs forward; <code>off</code>/<code>false</code>/<code>0</code> runs backward. <strong>Invert Boolean direction</strong> swaps this mapping. <strong>Duration</strong> sets the rate.</td></tr></tbody></table><p>Unavailable or invalid entity states stop the animation. The selected state refreshes in both editor and runtime. An <strong>SVG LineBox</strong> output can pass its calculated signed value to the line. This overrides the chosen direction source, but the outgoing line still needs <strong>Animation enabled</strong>. A zero or missing input stops it. Its <strong>SVG LineBox divisor (on handoff)</strong> sets the rate; the line keeps its own colors and style. See the <a href="./svg-linebox">SVG LineBox guide</a>.</p><h2 id="automatic-divisor-adjustment-how-and-why" tabindex="-1">Automatic divisor adjustment: how and why <a class="header-anchor" href="#automatic-divisor-adjustment-how-and-why" aria-label="Permalink to &quot;Automatic divisor adjustment: how and why&quot;">​</a></h2><p>With a fixed divisor, animation speed increases with the input value. For example, divisor <code>100</code> turns <code>10 W</code> into only <code>0.1</code> cycles/s, but <code>1500 W</code> into <code>15</code> cycles/s. Increasing the divisor slows high-power appliances such as heating or a cooker, while making small values very slow. Reducing it speeds up small values and can make large values difficult to follow visually.</p><p>Automation therefore adjusts the divisor whenever the value changes, using the selected <strong>target speed</strong>. It uses no fixed power bands and also works above 15,000. The calculation is:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Automatic divisor = absolute input value / target speed</span></span>
<span class="line"><span>Animation speed = absolute input value / automatic divisor</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>At <strong>1 cycle/s</strong>, the results are:</p><table tabindex="0"><thead><tr><th>Input value</th><th>Automatic divisor</th><th>Speed</th></tr></thead><tbody><tr><td>10</td><td>10</td><td>1 cycle/s</td></tr><tr><td>100</td><td>100</td><td>1 cycle/s</td></tr><tr><td>1500</td><td>1500</td><td>1 cycle/s</td></tr><tr><td>15,000</td><td>15,000</td><td>1 cycle/s</td></tr></tbody></table><p>This keeps motion similarly readable at low and high power. With automation enabled, speed represents the chosen target speed; it no longer indicates power magnitude. The sign still determines direction. Zero, missing values and invalid states stop animation.</p><h3 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h3><ol><li>Select SVG-Line and enable animation under <strong>Animation</strong>.</li><li>For a Home Assistant numeric source, choose <strong>Direction source → Numeric entity</strong>, enter the entity and enable <strong>Automatically adjust divisor (numeric entity)</strong>.</li><li>For a connected <strong>SVG LineBox</strong> or <a href="./svg-linebox-math"><strong>SVG LineBox Math</strong></a> output, enable <strong>Automatically adjust divisor (SVG LineBox)</strong> instead. This forwarded value takes precedence over the selected direction source.</li><li>Set the corresponding <strong>target speed</strong>. The default is <strong>1 cycle/s</strong>, with a range of <strong>0.05–5 cycles/s</strong>. A target of <code>0.5</code> means two seconds per cycle; <code>2</code> means half a second. Start at <code>1</code> and adjust it for your line style and dash spacing.</li></ol><p>Both automation settings are independent and initially disabled. Each manual divisor remains stored and takes effect again when its automation is disabled. <strong>Manual</strong> and <strong>Boolean entity</strong> modes still use their configured duration. Main-line animation inheritance continues to apply to ordinary branches; an actively forwarded LineBox value sets its outgoing line&#39;s own timing.</p><p>Cycles per second measure animation repetitions, not pixel speed. Line style, animation style and dash spacing affect visible motion. Automation provides a stable rate, while the target speed remains adjustable for each line.</p><h2 id="main-line-crossings-and-stacking" tabindex="-1">Main line, crossings, and stacking <a class="header-anchor" href="#main-line-crossings-and-stacking" aria-label="Permalink to &quot;Main line, crossings, and stacking&quot;">​</a></h2><p><strong>Main line / flow group</strong> assigns a line to another. <strong>Inherit main-line animation timing (keep own colors)</strong> adopts the timing and animation style while retaining the branch&#39;s colors during active flow. <strong>Synchronization</strong> offers <strong>same phase</strong> or <strong>arrive at collector together</strong>. When a branch is connected to a collector of a non-animated main line, it stops and displays the main line&#39;s base color, including arrowheads. Detaching restores its saved settings.</p><p>Under <strong>Crossing and z-index</strong>, choose <strong>overlay</strong>, <strong>gap</strong>, or <strong>bridge/arc</strong>, and <strong>automatic</strong>, <strong>above</strong>, <strong>below</strong>, or <strong>manual</strong> stacking. A higher z-index appears in front of a lower one. <strong>Pass clicks through</strong> affects runtime interaction. Neither crossing style nor z-index connects lines; use a collector or <a href="./svg-linebox">SVG LineBox</a> for that.</p><p>SVG-Line remains experimental. Crossing effects and synchronized animation can vary with path shape and browser.</p>`,38)])])}const u=e(i,[["render",s]]);export{p as __pageData,u as default};
